package ru.threediwell.fm.farm;

import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class MobileCorrectionsTest {
    /** Android libcore JSON.toString(NULL) returns "null", unlike the JVM test dependency. */
    private static class AndroidJson extends JSONObject {
        @Override public String optString(String key){return optString(key,"");}
        @Override public String optString(String key,String fallback){Object value=opt(key);return value==null?fallback:String.valueOf(value);}
    }
    private JSONObject printer()throws Exception{return new JSONObject().put("id","p").put("type","flashforge");}
    private JSONObject state()throws Exception{return new JSONObject().put("status","FINISH").put("status_raw","completed").put("seen_ago",0).put("file_name","Part.gcode");}
    private JSONObject file()throws Exception{return new AndroidJson().put("filename","Part.gcode").put("file_id",JSONObject.NULL).put("content_hash",JSONObject.NULL).put("is_printable",true).put("compatible_pids",new JSONArray().put("p"));}
    private JSONObject run(String source,Object hash)throws Exception{return new AndroidJson().put("run_id","r").put("printer_id","p").put("source",source).put("filename","Part.gcode").put("outcome_raw","finished").put("file_hash",hash).put("project_id",JSONObject.NULL).put("file_id",JSONObject.NULL).put("source_payload",new AndroidJson().put("server_sent",true));}
    private RepeatPrint.Last last(JSONObject row)throws Exception{return RepeatPrint.last(new JSONObject().put("runs",new JSONArray().put(row)),printer(),state(),0);}
    @Test public void androidNullReproducesPhoneFailureButNormalizesAbsentHash()throws Exception{JSONObject row=run("quick",JSONObject.NULL);assertEquals("null",row.optString("file_hash"));assertEquals("",last(row).hash());}
    @Test public void quickNullHashCanResolveAndKeepTaskAccounting()throws Exception{var last=last(run("quick",JSONObject.NULL));var target=new RepeatPrint.Target(last,file(),"","","p");assertSame(target,RepeatPrint.resolve(last,List.of(target),"p"));assertTrue(target.matches(new PrintRequest("","","Part.gcode","p",null,null)));}
    @Test public void projectWithoutRecordedHashStillRequiresExactOwnerAndFile()throws Exception{var last=last(run("project",JSONObject.NULL).put("project_id","pr").put("file_id","f"));var target=new RepeatPrint.Target(last,file().put("file_id","f").put("content_hash","real"),"pr","Project","p");assertSame(target,RepeatPrint.resolve(last,List.of(target),"p"));assertThrows(IllegalStateException.class,()->RepeatPrint.resolve(last,List.of(new RepeatPrint.Target(last,target.file,"other","","p")),"p"));}
    @Test public void realHashMismatchAndMissingCurrentHashStillFailClosed()throws Exception{var last=last(run("project","real").put("project_id","pr").put("file_id","f"));for(Object hash:new Object[]{JSONObject.NULL,"changed","null"})assertThrows(IllegalStateException.class,()->RepeatPrint.resolve(last,List.of(new RepeatPrint.Target(last,file().put("file_id","f").put("content_hash",hash),"pr","","p")),"p"));}
    @Test public void literalNullStringIsNotTreatedAsAbsentHash()throws Exception{var last=last(run("quick","null"));assertEquals("null",last.hash());assertThrows(IllegalStateException.class,()->RepeatPrint.resolve(last,List.of(new RepeatPrint.Target(last,file(),"","","p")),"p"));}
    @Test public void nullProjectIdentifiersDoNotBecomeValidLinks()throws Exception{assertThrows(IllegalStateException.class,()->last(run("project",JSONObject.NULL)));}
    @Test public void nullStagingPayloadDoesNotReplaceTheRealFilename()throws Exception{var row=run("quick",JSONObject.NULL).put("source_payload",new AndroidJson().put("staging_file",JSONObject.NULL).put("server_sent",true));assertEquals("Part.gcode",last(row).filename());}
    @Test public void nullFilenameCannotBecomeARepeatableFilename()throws Exception{assertThrows(IllegalStateException.class,()->last(run("quick",JSONObject.NULL).put("filename",JSONObject.NULL)));}
    @Test public void missingAndExplicitNullProduceTheSameConfirmationSnapshot()throws Exception{var last=last(run("quick",JSONObject.NULL));var a=new RepeatPrint.Target(last,file(),"","","p");JSONObject other=file();other.remove("content_hash");other.remove("file_id");assertTrue(a.same(new RepeatPrint.Target(last,other,"","","p")));other.put("mtime",20);assertFalse(a.same(new RepeatPrint.Target(last,other,"","","p")));}
    private static final class Memory implements NotificationBook.Store {String value="[]";public String read(){return value;}public void write(String v){value=v;}}
    @Test public void notificationReadStateSurvivesRecreation(){Memory m=new Memory();NotificationBook b=new NotificationBook(m);b.upsert("farm/user","1","queued","Print","Queued",1);assertEquals(1,b.unread("farm/user"));b.readAll("farm/user");assertEquals(0,new NotificationBook(m).unread("farm/user"));}
    @Test public void pollingAndProgressDoNotCreateRepeatedUnreadNotifications(){Memory m=new Memory();NotificationBook b=new NotificationBook(m);assertTrue(b.upsert("s","j","uploading","File","10%",1));b.readAll("s");assertFalse(b.upsert("s","j","uploading","File","60%",2));assertEquals(0,b.unread("s"));assertEquals("60%",b.entries("s").get(0).message());assertEquals(1,b.entries("s").get(0).time());}
    @Test public void failureAfterReadBecomesUnreadAndRemainsInLocalHistory(){NotificationBook b=new NotificationBook(new Memory());b.upsert("s","j","uploading","File","Uploading",1);b.readAll("s");assertTrue(b.upsert("s","j","failed","File","Failed",2));assertEquals(1,b.unread("s"));assertEquals("Failed",b.entries("s").get(0).message());}
    @Test public void accountsAndServersHaveSeparateNotificationCounters(){NotificationBook b=new NotificationBook(new Memory());b.upsert("farm/a","j","x","A","A",1);b.upsert("farm/b","j","x","B","B",2);b.upsert("other/a","j","x","C","C",3);b.readAll("farm/a");assertEquals(0,b.unread("farm/a"));assertEquals(1,b.unread("farm/b"));assertEquals("C",b.entries("other/a").get(0).message());}
    @Test public void historyIsBoundedAndKeepsRecentFailures(){NotificationBook b=new NotificationBook(new Memory());for(int i=0;i<110;i++)b.upsert("s","j"+i,"failed","File","Failed",i);assertEquals(100,b.entries("s").size());assertEquals("j109",b.entries("s").get(0).key());}
    @Test public void corruptNotificationHistoryDoesNotInventMessages(){Memory m=new Memory();m.value="invalid";assertEquals(0,new NotificationBook(m).unread("s"));}
    @Test public void returningPrinterErrorBecomesUnreadAgainWithoutErasingHistory(){NotificationBook b=new NotificationBook(new Memory());b.upsert("s","printer:p:e","error","P","Error",1);b.readAll("s");b.markAbsent("s","printer:p:",Set.of());assertEquals(1,b.entries("s").size());assertTrue(b.upsert("s","printer:p:e","error","P","Error",2));assertEquals(1,b.unread("s"));}
    @Test public void resolvingOnePrinterDoesNotResolveAnotherAccountOrPrinter(){NotificationBook b=new NotificationBook(new Memory());b.upsert("s","printer:p:e","error","P","Error",1);b.upsert("other","printer:p:e","error","P","Error",1);b.upsert("s","printer:q:e","error","Q","Error",1);b.markAbsent("s","printer:p:",Set.of());assertFalse(b.upsert("other","printer:p:e","error","P","Error",2));assertFalse(b.upsert("s","printer:q:e","error","Q","Error",2));}
    @Test public void resolvedErrorStateSurvivesRecreation(){Memory m=new Memory();NotificationBook b=new NotificationBook(m);b.upsert("s","printer:p:e","error","P","Error",1);b.readAll("s");b.markAbsent("s","printer:p:",Set.of());b=new NotificationBook(m);assertTrue(b.upsert("s","printer:p:e","error","P","Error",2));assertEquals(1,b.unread("s"));}
    @Test public void readingNotificationsCannotClearUnknownPrintJournal()throws Exception{String[] saved={""};PrintJournal journal=new PrintJournal(new PrintJournal.Store(){public String read(){return saved[0];}public boolean write(String v){saved[0]=v;return true;}public boolean clear(){saved[0]="";return true;}});journal.begin("farm",new PrintRequest("","","Part.gcode","p",null,null),1);NotificationBook b=new NotificationBook(new Memory());b.upsert("farm/a","unknown","x","Print","Unknown",1);b.readAll("farm/a");assertTrue(journal.blocks("farm","p"));assertThrows(IllegalStateException.class,()->journal.begin("farm",new PrintRequest("","","Part.gcode","p",null,null),2));}
    @Test public void projectProgressUsesCorePartMetricEvenWhenPieceTotalsDiffer()throws Exception{var p=new JSONObject().put("parts_count",13).put("done_count",12).put("printed_total",999).put("required_total",1000);assertEquals(92,ProjectProgress.of(p).percent());assertEquals(12,ProjectProgress.of(p).done());}
    @Test public void projectScreenshotExamplesAndEmptyPlan()throws Exception{for(int[] pair:new int[][]{{1,10,10},{0,10,0},{12,13,92},{6,6,100},{0,0,0}})assertEquals(pair[2],ProjectProgress.of(new JSONObject().put("done_count",pair[0]).put("parts_count",pair[1])).percent());}
    @Test public void invalidProjectCountsNeverOverflowProgressFrame()throws Exception{assertEquals(100,ProjectProgress.of(new JSONObject().put("done_count",999).put("parts_count",6)).percent());assertEquals(0,ProjectProgress.of(new JSONObject().put("done_count",-1).put("parts_count",6)).percent());}
    private JSONObject tray(int index,String type,Object percent)throws Exception{return new JSONObject().put("index",index).put("unit",index/4).put("tray",index%4).put("type",type).put("color","FF671FFF").put("remain",percent);}
    private JSONObject live(JSONArray trays)throws Exception{return state().put("ams_trays",trays).put("ams_now",2);}
    private JSONObject stock(int index,boolean external,Object remaining,Object total)throws Exception{return new JSONObject().put("slots",new JSONArray().put(new JSONObject().put("index",index).put("external",external).put("spool",new JSONObject().put("material","PETG").put("color_hex","#aaaaaa").put("weight_remaining_g",remaining).put("weight_total_g",total))));}
    private MaterialSlots.Slot first(JSONObject state,long age,JSONObject stock)throws Exception{return MaterialSlots.of(printer(),state,age,stock).get(0);}
    @Test public void telemetrySlotsRemainAvailableWithoutInventoryModule()throws Exception{var slot=first(live(new JSONArray().put(tray(2,"PETG",68))),0,null);assertEquals(68,slot.percent());assertTrue(slot.active());assertEquals("#FF671F",slot.color());}
    @Test public void inventoryPercentUsesOriginalSpoolWeightNotAssumedOneKilo()throws Exception{var slot=first(live(new JSONArray().put(tray(2,"PETG",-1))),0,stock(2,false,340,500));assertEquals(68,slot.percent());}
    @Test public void unknownNullAndNegativeRemainAreNotZeroOrFull()throws Exception{for(Object value:new Object[]{JSONObject.NULL,-1,101,"?"})assertEquals(-1,first(live(new JSONArray().put(tray(2,"PETG",value))),0,null).percent());}
    @Test public void missingZeroAndNegativeOriginalWeightsDoNotInventPercent()throws Exception{for(Object total:new Object[]{JSONObject.NULL,0,-1})assertEquals(-1,first(live(new JSONArray().put(tray(2,"PETG",-1))),0,stock(2,false,300,total)).percent());}
    @Test public void emptyTelemetryWinsOverOldBoundSpool()throws Exception{var slot=first(live(new JSONArray().put(tray(2,"Empty",-1))),0,stock(2,false,1000,1000));assertTrue(slot.empty());assertFalse(slot.active());assertEquals(-1,slot.percent());assertEquals("",slot.color());}
    @Test public void explicitlyReportedEmptyZeroCanShowZeroPercent()throws Exception{var slot=first(live(new JSONArray().put(tray(2,"Empty",0))),0,stock(2,false,1000,1000));assertTrue(slot.empty());assertEquals(0,slot.percent());}
    @Test public void stalePrinterDoesNotShowCurrentFeedOrCurrentPercent()throws Exception{var slot=first(live(new JSONArray().put(tray(2,"PETG",68))),6500,stock(2,false,340,500));assertTrue(slot.stale());assertFalse(slot.active());assertEquals(-1,slot.percent());}
    @Test public void cfsUsesSeparateTelemetryAndDoesNotGuessAmbiguousLoadedSlot()throws Exception{JSONObject s=state().put("cfs_trays",new JSONArray().put(tray(0,"PETG",JSONObject.NULL).put("percent",72).put("label","T1A"))).put("cfs_now",-1).put("cfs_now_candidates",new JSONArray().put(0).put(1));var slot=first(s,0,null);assertEquals("CFS 1",slot.group());assertEquals("T1A",slot.position());assertEquals(72,slot.percent());assertFalse(slot.active());s.put("cfs_now",0);assertTrue(first(s,0,null).active());}
    @Test public void amsHtDoesNotCreatePhantomRegularUnits()throws Exception{var rows=MaterialSlots.of(printer(),live(new JSONArray().put(tray(512,"PLA",100))),0,null);assertEquals(1,rows.size());assertEquals("AMS HT",rows.get(0).group());assertEquals("AMS HT · 1",rows.get(0).position());}
    @Test public void externalInventoryBindingHasItsOwnPercentage()throws Exception{var slot=first(state(),0,stock(-1,true,417,1000));assertTrue(slot.external());assertEquals(42,slot.percent());}
    @Test public void legacySlotZeroIsNotGuessedToBeExternal()throws Exception{var slot=first(state(),0,stock(0,false,417,1000));assertFalse(slot.external());assertTrue(slot.stale());assertEquals(-1,slot.percent());}
    @Test public void leftExternalSettingDoesNotInheritRightSpoolWeight()throws Exception{JSONObject s=state().put("ext_trays",new JSONObject().put("255",new JSONObject().put("type","PETG")).put("254",new JSONObject().put("type","PLA")));var slots=MaterialSlots.of(printer(),s,0,stock(-1,true,680,1000));assertEquals(2,slots.size());assertEquals(68,slots.get(0).percent());assertEquals(-1,slots.get(1).percent());}
    @Test public void unconfirmedInventorySlotCannotOverrideLiveRemaining()throws Exception{JSONObject b=stock(2,false,340,500);b.getJSONArray("slots").getJSONObject(0).put("unconfirmed",true);assertEquals(80,first(live(new JSONArray().put(tray(2,"PETG",80))),0,b).percent());}
    @Test public void invalidColorsAreNeutralAndRgbaUsesCorrectChannelOrder(){assertEquals("",MaterialSlots.color("orange"));assertEquals("#FF671F",MaterialSlots.color("#FF671FFF"));assertEquals("#001122",MaterialSlots.color("001122"));}
    @Test public void displayModelsNeverMutateTelemetryOrInventory()throws Exception{JSONObject s=live(new JSONArray().put(tray(2,"PETG",68))),b=stock(2,false,340,500);String a=s.toString(),c=b.toString();MaterialSlots.of(printer(),s,0,b);assertEquals(a,s.toString());assertEquals(c,b.toString());}
}
